mapper.select:
SELECT COUNT(*)
FROM auth_principal_role_assignment assignment
JOIN auth_role_capability role_capability
  ON role_capability.role_id = assignment.role_id
JOIN auth_capability capability
  ON capability.capability_id = role_capability.capability_id
 AND capability.capability_code = #{capability}
JOIN auth_data_scope data_scope
  ON data_scope.scope_id = assignment.data_scope_id
WHERE assignment.principal_id = #{principalId}
  AND assignment.valid_from <= #{at}
  AND (assignment.valid_to IS NULL OR assignment.valid_to > #{at})
  AND data_scope.valid_from <= #{at}
  AND (data_scope.valid_to IS NULL OR data_scope.valid_to > #{at})
  AND data_scope.scope_type = 'COMPANY'
  AND data_scope.company_id = #{companyId}

SELECT attendance_source_id
FROM attendance_source
WHERE attendance_source_id = #{sourceId}
  AND company_id = #{companyId}
  AND status = 'ACTIVE'
  AND source_type IN ('DEVICE_EXCEL', 'STANDARD_XLSX')

