) VALUES (
    #{batchId}, #{sourceId}, #{companyId},
    NULL, NULL, 1, #{actorId}, #{createdAt}
)

INSERT INTO punch_import_file (
    punch_import_file_id, punch_import_batch_id, attendance_source_id,
    company_id, content_sha256, original_filename, stored_object_ref,
    file_size_bytes, content_type, malware_scan_status, template_version,
    field_contract_digest, uploaded_by, uploaded_at
) VALUES (
    #{fileId}, #{batchId}, #{sourceId}, #{companyId}, #{sha256},
    #{filename}, #{objectRef}, #{size}, #{contentType}, 'CLEAN',
    #{templateVersion}, #{contractDigest}, #{actorId}, #{uploadedAt}
)

INSERT INTO punch_import_state_event (
    punch_import_state_event_id, punch_import_batch_id, sequence_number,
    from_state, to_state, reason_code, request_id, actor_id, created_at
) VALUES (
    #{eventId}, #{batchId}, #{sequence}, #{fromState}, #{toState},
    #{reasonCode}, #{requestId}, #{actorId}, #{createdAt}
)

mapper.select:
SELECT COALESCE(MAX(sequence_number), 0) + 1
FROM punch_import_state_event
WHERE punch_import_batch_id = #{batchId}

mapper.update:
UPDATE punch_import_batch
SET row_version = row_version + 1
WHERE punch_import_batch_id = #{batchId}
  AND row_version = #{expectedVersion}

